int[] twoSumSorted(int[] nums, int target) {
  int[][] pairs = new int[nums.length][2];
  for (int i = 0; i < nums.length; i++) pairs[i] = new int[] { nums[i], i };
  Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));
  int left = 0, right = pairs.length - 1;
  while (left < right) {
    int total = pairs[left][0] + pairs[right][0];
    if (total == target) return new int[] { pairs[left][1], pairs[right][1] };
    if (total < target) left++; else right--;
  }
  return new int[0];
}

