class LRUCacheSimple:
    def __init__(self, capacity):
        self.capacity = capacity
        self.clock = 0
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return -1
        value, _ = self.data[key]
        self.clock += 1
        self.data[key] = (value, self.clock)
        return value

    def put(self, key, value):
        self.clock += 1
        self.data[key] = (value, self.clock)
        if len(self.data) > self.capacity:
            oldest = min(self.data, key=lambda k: self.data[k][1])
            del self.data[oldest]

typescript.code:
export class LRUCacheSimple {
  private clock = 0;
  private data = new Map<number, { value: number; used: number }>();
  constructor(private capacity: number) {}
  get(key: number): number {
    const item = this.data.get(key);
    if (!item) return -1;
    item.used = ++this.clock;
    return item.value;
  }
  put(key: number, value: number): void {
    this.data.set(key, { value, used: ++this.clock });
    if (this.data.size <= this.capacity) return;
    let oldestKey = key;
    let oldest = Infinity;
    for (const [k, item] of this.data) if (item.used < oldest) { oldest = item.used; oldestKey = k; }
    this.data.delete(oldestKey);
  }
}

