class LRUCacheSimple {
  record Entry(int value, int used) {}
  private final int capacity;
  private int clock = 0;
  private final Map<Integer, Entry> data = new HashMap<>();
  LRUCacheSimple(int capacity) { this.capacity = capacity; }
  int get(int key) {
    Entry item = data.get(key);
    if (item == null) return -1;
    data.put(key, new Entry(item.value(), ++clock));
    return item.value();
  }
  void put(int key, int value) {
    data.put(key, new Entry(value, ++clock));
    if (data.size() > capacity) data.remove(data.entrySet().stream().min(Comparator.comparingInt(e -> e.getValue().used())).get().getKey());
  }
}

