List<Integer> topKBucket(int[] nums, int k) {
  Map<Integer, Integer> counts = new HashMap<>();
  for (int value : nums) counts.merge(value, 1, Integer::sum);
  List<List<Integer>> buckets = new ArrayList<>();
  for (int i = 0; i <= nums.length; i++) buckets.add(new ArrayList<>());
  for (Map.Entry<Integer, Integer> entry : counts.entrySet()) buckets.get(entry.getValue()).add(entry.getKey());
  List<Integer> out = new ArrayList<>();
  for (int count = buckets.size() - 1; count >= 0 && out.size() < k; count--) out.addAll(buckets.get(count));
  return out.subList(0, k);
}
